def calculate(expr):
    stack = []
    num = 0
    prev = '+'
    for ch in expr + '+':
        if ch.isdigit():
            num = num * 10 + int(ch)
            continue
        if prev == '+':
            stack.append(num)
        elif prev == '-':
            stack.append(-num)
        elif prev == '*':
            stack.append(stack.pop() * num)
        else:
            top = stack.pop()
            q = abs(top) // num
            stack.append(q if top >= 0 else -q)
        prev = ch
        num = 0
    return sum(stack)
